import sys
import json

sys.path.insert(0, '/workspace/skills/state-customer-support')

from schemas import CSEnvironmentData
from environment import CustomerSupportEnvironment

env_data = CSEnvironmentData.load()
env = CustomerSupportEnvironment(env_data, now='2026-06-15T10:00:00')

results = {}

try:
    results['order_before'] = env.get_order({'order_id': 'ORD-420D7A'})
except Exception as e:
    results['order_before_error'] = str(e)

try:
    results['exchange_policy'] = env.get_policies({'topic': 'exchange'})
except Exception as e:
    results['exchange_policy_error'] = str(e)

try:
    results['preview'] = env.process_exchange({'item_id': 'ITEM-7D120E', 'new_product_id': 'PROD-F9994E'})
except Exception as e:
    results['preview_error'] = str(e)

try:
    results['confirm'] = env.process_exchange({'item_id': 'ITEM-7D120E', 'new_product_id': 'PROD-F9994E', 'confirm': True})
except Exception as e:
    results['confirm_error'] = str(e)

try:
    results['refund_policy'] = env.get_policies({'topic': 'refund'})
except Exception as e:
    results['refund_policy_error'] = str(e)

try:
    results['verify'] = env.get_order({'order_id': 'ORD-420D7A'})
except Exception as e:
    results['verify_error'] = str(e)

try:
    env_data_out = CSEnvironmentData(
        products=list(env.products.values()),
        orders=list(env.orders.values()),
        order_items=list(env.order_items.values()),
        customers=list(env.customers.values()),
        warranties=list(env.warranties.values()),
    )
    env_data_out.save()
    results['saved'] = True
except Exception as e:
    results['save_error'] = str(e)

with open('/workspace/exchange_final.json', 'w') as f:
    json.dump(results, f, indent=2, default=str)
